corrected_code:
app.patch('/api/profile/:id', (req, res) => {
  Profile.findOne({ _id: req.params.id, userId: req.user.id })
    .then(doc => {
      if (!doc) return res.status(404).send('Not Found');
      Object.assign(doc, req.body);
      return doc.save();
    })
    .then(() => res.send('OK'));
});
